const item = $input.first().json;
const aiResponse = item.content || (item.message && item.message.content) || item.text;

function cleanJson(text) {
  if (!text) return null;
  let cleaned = text.replace(/```json\s*/g, "").replace(/```\s*$/g, "");
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    cleaned = cleaned.substring(firstBrace, lastBrace + 1);
  }
  return cleaned;
}

try {
  const cleanedJson = cleanJson(aiResponse);
  if (!cleanedJson) throw new Error("Respuesta vacía");
  return JSON.parse(cleanedJson);
} catch (e) {
  return { error: "Error parsing JSON", message: e.message, raw: aiResponse };
}

